# try to find column function G(left) and row F(top) consistent across all
sols=[]
for pa in permutations(zip(A,Acells)):
    for pb in permutations(zip(B,Bcells)):
        m = dict(pa)|dict(pb)
        # candidate F from tops
        tops = sorted(set(t for (t,l),(r,c) in m.items()))
        # require F monotone-ish? just collect and look
        f = {t:r for (t,l),(r,c) in m.items()}
        g = {l:c for (t,l),(r,c) in m.items()}
        sols.append((pa,pb,f,g))
# look for solutions where f is a threshold function
good=[]
for pa,pb,f,g in sols:
